import React from "react";

const TaskList = ({ quadrant, tasks, deleteTask }) => {
  const quadrantTasks = tasks.filter((task) => task.quadrant === quadrant);

  return (
    <div className="list-group">
      {quadrantTasks.map((task) => (
        <div key={task.id} className="list-group-item d-flex justify-content-between align-items-center">
          <span>{task.text}</span>
          <button className="btn btn-sm btn-danger" onClick={() => deleteTask(task.id)}>
            Delete
          </button>
        </div>
      ))}
    </div>
  );
};

export default TaskList;
